[tikz]
\begin{tikzpicture}[every node/.style={font=\large},scale=0.5]
\usetikzlibrary{angles,quotes}
\coordinate (A) at (6,0);
\coordinate (B) at (0,0);
\coordinate (C) at (-2.92,8.03);
\draw (A)--(B) node[midway,below] {$6$};
\draw (A)--(C) node[midway,above right] {$12$};
\draw (B)--(C);
\pic[draw,"$110^{\circ}$",angle radius=0.9cm,angle eccentricity=1.35] {angle=A--B--C};
